def _hex_pts(af, rot=0.0):
    R = af / (2.0 * math.cos(math.pi / 6.0))
    return [(R * math.cos(math.radians(rot + 60.0 * i)),
             R * math.sin(math.radians(rot + 60.0 * i))) for i in range(6)]

def _box(l, w, h):
    return cq.Workplane("XY").box(l, w, h, centered=(True, True, False)).val()

def _cyl(r, h, x=0.0, y=0.0, z=0.0):
    return cq.Workplane("XY", origin=(x, y, z)).circle(r).extrude(h).val()

def _hexprism(af, h, x=0.0, y=0.0, z=0.0, rot=0.0):
    return (cq.Workplane("XY", origin=(x, y, z))
            .polyline(_hex_pts(af, rot)).close().extrude(h).val())

def build(p):
    L, W, H = p.coupon_l, p.coupon_w, p.coupon_h
    zf = H - p.coupon_pocket_depth
    body = _box(L, W, H)
    afs = [p.af_1, p.af_2, p.af_3, p.af_4, p.af_5]
    for i, af in enumerate(afs):
        x = p.coupon_pitch * (i - 2.0)
        # hex nut pocket
        body = body.cut(_hexprism(af, p.coupon_pocket_depth + 1.0, x, 0.0, zf))
        # 45 degree stepped entry chamfer
        steps = 4
        hs = p.chamfer_h / steps
        for k in range(steps):
            body = body.cut(_hexprism(af + 2.0 * hs * (k + 1), hs + 0.01,
                                      x, 0.0, H - p.chamfer_h + k * hs))
        # bolt clearance hole through the floor
        body = body.cut(_cyl(p.bolt_clear_d / 2.0, zf + 2.0, x, 0.0, -1.0))
    # marker post marking pocket 1 (left end)
    body = body.fuse(_cyl(2.5, 3.0, -L / 2.0 + 3.0, 0.0, H))
    return body
